<?php $title='Settings';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){foreach($_POST as $k=>$v)$pdo->prepare("INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)")->execute([$k,trim($v)]);}$settings=$pdo->query("SELECT setting_key,setting_value FROM settings")->fetchAll(PDO::FETCH_KEY_PAIR);?><h1>Business Settings</h1><form method="post" class="card border-0 shadow-sm p-4 mt-3"><div class="row g-3"><?php foreach(['business_name'=>'Business Name','phone'=>'Phone','whatsapp'=>'WhatsApp Number','email'=>'Email','address'=>'Address','business_hours'=>'Business Hours'] as $k=>$label):?><div class="col-md-6"><label class="form-label"><?=e($label)?></label><input name="<?=e($k)?>" value="<?=e($settings[$k]??'')?>" class="form-control"></div><?php endforeach;?><div class="col-12"><button class="btn btn-primary">Save Settings</button></div></div></form><?php require 'includes/footer.php';?>